```php
/**
 * Fetches the size of a given Wikipedia section (in characters of wikitext).
 *
 * @param string $articleTitle The title of the Wikipedia article.
 * @param string $sectionTitle The title of the section to fetch the size of.
 * @return int The size of the section in characters of wikitext.
 */
public function getSectionSize($articleTitle, $sectionTitle) {
    // Fetch the content of the article
    $articleContent = $this->fetchArticleContent($articleTitle);

    // Split the content into sections
    $sections = $this->splitContentIntoSections($articleContent);

    // Find the section by title
    $section = $this->findSectionByTitle($sections, $sectionTitle);

    // Return the size of the section
    return strlen($section);
}
